class Solution:
    def isAdditiveNumber(self, num: str) -> bool:
        sequence = []
        def search(start):
            if start == len(num):
                return len(sequence) >= 3
            value = 0
            for end in range(start, len(num)):
                if end > start and num[start] == '0':
                    break
                value = value * 10 + int(num[end])
                if len(sequence) >= 2:
                    expected = sequence[-2] + sequence[-1]
                    if value < expected:
                        continue
                    if value > expected:
                        break
                sequence.append(value)
                if search(end + 1):
                    return True
                sequence.pop()
            return False
        return search(0)
